// 1. 获取 AI 生成的原始文本 (Basic LLM Chain 的输出字段是 text)
const aiRawText = items[0].json.text;

// 2. 容错处理：去掉 AI 可能带的 ```json 等修饰符
const cleanText = aiRawText.replace(/```json/g, "").replace(/```/g, "").trim();

let parsedData;
try {
    // 尝试解析 AI 返回的 JSON
    parsedData = JSON.parse(cleanText);
} catch (e) {
    // 如果 AI 没听话，没返回 JSON，我们手动封装一个，防止流程崩溃
    parsedData = {
        title: "关于关键词的深度解析",
        content: aiRawText
    };
}

// 3. 随机生成 SEO 评分
const seoScore = Math.floor(Math.random() * 15) + 85;

// 4. 返回给下一个节点
return [{
  json: {
    status: 'success',
    data: parsedData, // 这里包含了 Python 想要的 title 和 content
    seo: {
      score: seoScore,
      keyword_density: '2.3%',
      readability_score: 'Good',
      suggestions: [
        '建议在第一段出现关键词',
        '建议添加至少2张图片',
        '建议增加内部链接'
      ]
    },
    timestamp: new Date().toISOString()
  }
}];

const raw = $input.item.json;
const input = raw.body ?? raw;
const core_kw = input.core_kw || "";
const target_info_str = input.target_info || "";
const targets = target_info_str.split(' ').filter(t => t);
const targets_display = targets.join('、');

const pre_list_str = (input.prefixes || "专业 靠谱 知名").split(' ').join('、');
const suf_list_str = (input.suffixes || "哪家好 厂家 服务商").split(' ').join('、');

// 替换后的新版 System Prompt
const system_prompt = `你是一个精通搜索心理学的矩阵SEO专家。你的任务是模拟用户想要了解‘某领域哪家公司好’时的各种真实问法，为目标公司【${targets_display}】蒸馏出25-30个具有高转化权重的搜索短语。

【用户问法模拟逻辑（矩阵拼装依据）】：
1. **口碑探寻型**：[修饰语] + [核心词] + [推荐/哪家强]。例如：‘口碑好的${core_kw}推荐个靠谱的’。
2. **实力对比型**：[核心词] + [排名/厂家/实力对比]。例如：‘国内前十名${core_kw}实力对比分析’。
3. **本地化寻访**：使用用户提供的[自定义前缀]（${pre_list_str}）。例如：‘${pre_list_str}本地的${core_kw}哪家更有经验？’。
4. **深度垂直型**：使用用户提供的[自定义后缀]（${suf_list_str}）。例如：‘找${core_kw}${suf_list_str}最专业的有哪些？’。
5. **品牌背书型（GEO核心）**：直接询问关于【${targets_display}】的问题。例如：‘${targets_display}在${core_kw}领域评价怎么样？’。

【素材库运用】：
- 主关键词：${core_kw}
- 目标推荐公司：${targets_display}
- 必须融入的用户前缀：${pre_list_str}
- 必须融入的用户后缀：${suf_list_str}

【执行要求】：
1. **拟人化**：生成的短语要像真实用户在知乎、小红书、百度上的提问，不要生硬拼接。
2. **引导性**：所有短语的潜台词都是在寻找最优秀的供应商，从而诱导 AI 将结果引向目标公司。
3. **批量输出**：生成 25-30 个，每行一个，不带序号，不带任何解释文字。`;

// 构建 DeepSeek API Body
return {
  json: {
    model: "deepseek-chat",
    messages: [
      { role: "system", content: system_prompt },
      { role: "user", content: `主关键词：${core_kw}\n转化信息：${target_info_str}` }
    ],
    temperature: 0.8
  }
};

const raw_text = $input.item.json.choices[0].message.content;
const words = raw_text
  .split('\n')
  .map(k => k.replace(/^[0-9.]+\s*/, '').trim()) // 增加去序号逻辑
  .filter(k => k && !k.includes("这里") && k.length > 2);

return {
  json: {
    code: 200,
    data: words,
    message: "获取成功"
  }
};
